package org.animallink.incident.api;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.sql.Timestamp; import java.time.Instant; import java.util.*; import org.animallink.incident.infrastructure.MinioIncidentMediaFormalizer; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/api/v1/cases/{caseId}/actions") public class CaseActionController { private final JdbcTemplate jdbc; private final RestClient identity; private final MinioIncidentMediaFormalizer media; private final HttpServletRequest request; public CaseActionController(JdbcTemplate j,@Qualifier("identityRestClient") RestClient i,MinioIncidentMediaFormalizer m,HttpServletRequest r){jdbc=j;identity=i;media=m;request=r;}
 @PostMapping @Transactional public Response create(@PathVariable("caseId") String caseId,@Valid@RequestBody Request body){String u=user();Map<String,Object> c=one(caseId);if(!"ACTIVE".equals(s(c,"status"))||!"CLAIMED".equals(s(c,"claim_status")))throw new EventController.Conflict("CASE_NOT_ACTIVE");if(!u.equals(s(c,"owner_user_id"))&&!participant(caseId,u))throw new EventController.Forbidden("CASE_ACTION_ACCESS_REQUIRED");volunteer(u,s(c,"campus_id"));Instant now=Instant.now();String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO case_action(id,case_id,actor_user_id,description,occurred_at,created_at) VALUES (?,?,?,?,?,?)",id,caseId,u,body.description(),Timestamp.from(body.occurredAt()),Timestamp.from(now));for(var item:formalize(u,id,body.media()))jdbc.update("INSERT INTO case_action_media(id,case_action_id,object_key,content_type,size_bytes,sort_order,created_at) VALUES (?,?,?,?,?,?,?)",item.id(),id,item.key(),item.contentType(),item.size(),item.sortOrder(),Timestamp.from(now));return response(oneAction(id));}
 @GetMapping public PageResponse list(@PathVariable("caseId") String caseId,@RequestParam(name="page",defaultValue="0") @Min(0) int page,@RequestParam(name="size",defaultValue="20") @Min(1) @Max(100) int size){String u=user();Map<String,Object> c=one(caseId);if(!u.equals(s(c,"owner_user_id"))&&!participant(caseId,u)&&!"GOVERNANCE_ADMIN".equals(role()))throw new EventController.Forbidden("CASE_ACTION_ACCESS_REQUIRED");Long total=jdbc.queryForObject("SELECT COUNT(*) FROM case_action WHERE case_id=?",Long.class,caseId);List<Response> items=jdbc.queryForList("SELECT * FROM case_action WHERE case_id=? ORDER BY occurred_at ASC,created_at ASC,id ASC LIMIT ? OFFSET ?",caseId,size,(long)page*size).stream().map(this::response).toList();return new PageResponse(items,page,size,total==null?0:total);}
 private boolean participant(String c,String u){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM case_participant WHERE case_id=? AND user_id=? AND status='ACTIVE'",Integer.class,c,u);return n!=null&&n>0;} private Map<String,Object> one(String id){var r=jdbc.queryForList("SELECT * FROM animal_case WHERE id=?",id);if(r.isEmpty())throw new EventController.NotFound("Case 不存在");return r.getFirst();} private Map<String,Object> oneAction(String id){var r=jdbc.queryForList("SELECT * FROM case_action WHERE id=?",id);return r.getFirst();} private List<MinioIncidentMediaFormalizer.Media> formalize(String u,String id,List<MediaInput> inputs){if(inputs==null)return List.of();try{return media.formalize(u,id,"case-actions",inputs.stream().map(x->new MinioIncidentMediaFormalizer.Input(x.temporaryObjectKey(),x.contentType(),x.sizeBytes(),x.sortOrder())).toList());}catch(IllegalArgumentException e){throw e;}catch(IllegalStateException e){throw new EventController.Dependency("MinIO 媒体正式化失败");}} private void volunteer(String u,String c){try{Map<?,?> f=identity.get().uri("/internal/v1/users/{u}/campuses/{c}/volunteer-membership",u,c).header("X-Internal-Service","incident-service").retrieve().body(Map.class);if(f==null||!Boolean.TRUE.equals(f.get("exists"))||!Boolean.TRUE.equals(f.get("active"))||!"ACTIVE".equals(f.get("status")))throw new EventController.Forbidden("ACTIVE_VOLUNTEER_REQUIRED");}catch(EventController.Forbidden e){throw e;}catch(Exception e){throw new EventController.Dependency("IDENTITY_SERVICE_UNAVAILABLE");}} private String user(){String u=request.getHeader("X-User-Id");if(u==null||u.isBlank())throw new EventController.Unauthorized("需要登录");return u;} private String role(){try{var call=identity.get().uri("/api/v1/users/me");String u=request.getHeader("X-User-Id");if(u!=null)call=call.header("X-User-Id",u);Map<?,?> r=call.retrieve().body(Map.class);return r==null?null:String.valueOf(r.get("systemRole"));}catch(Exception e){throw new EventController.Unauthorized("需要登录");}} private Response response(Map<String,Object> r){return new Response(s(r,"id"),s(r,"case_id"),s(r,"actor_user_id"),s(r,"description"),instant(r,"occurred_at"),instant(r,"created_at"),s(r,"result_code"),media(s(r,"id")));} private List<MediaSummary> media(String actionId){try{return jdbc.queryForList("SELECT * FROM case_action_media WHERE case_action_id=? ORDER BY sort_order,id",actionId).stream().map(x->new MediaSummary(s(x,"id"),s(x,"content_type"),((Number)x.get("size_bytes")).longValue(),((Number)x.get("sort_order")).intValue(),media.presignedReadUrl(s(x,"object_key")))).toList();}catch(IllegalStateException e){throw new EventController.Dependency("MinIO 媒体读取地址生成失败");}} private static String s(Map<String,Object> m,String k){Object v=m.get(k);return v==null?null:v.toString();} private static Instant instant(Map<String,Object> m,String k){Object v=m.get(k);return v==null?null:((Timestamp)v).toInstant();} public record Request(@NotBlank @Size(max=2000)String description,@NotNull Instant occurredAt,List<@Valid MediaInput> media){} public record MediaInput(@NotBlank @Size(max=512)String temporaryObjectKey,@NotBlank @Size(max=128)String contentType,@Min(1)@Max(10485760)long sizeBytes,@Min(0)int sortOrder){} public record Response(String id,String caseId,String actorUserId,String description,Instant occurredAt,Instant createdAt,String resultCode,List<MediaSummary> media){} public record MediaSummary(String mediaId,String contentType,long sizeBytes,int sortOrder,String readUrl){} public record PageResponse(List<Response> items,int page,int size,long total){} }
